MultiLanguageSpellData['ru'][353859] = {name = "Летний чащобник", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Этот упрямый и гордый чащобник не желает никого слушаться – но раз признав хозяина, он остается верным ему до конца.\"\nКовенант:\nночной народец\nИсточник:\nсбежавший чащобник\nЗона:\nКортия"}
