MultiLanguageSpellData['ru'][356382] = {name = "Страдания", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Клетки для душ и освободившиеся души время от времени испускают крики отчаяния.\n Жертвы в радиусе 3 м от места попадания получают 40 ед. урона от темной магии и отбрасываются.\n На месте попадания появляется зона отчаяния, наносящие 15 ед. урона от темной магии раз в секунду."}
MultiLanguageSpellData['ru'][356383] = {name = "Страдания", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Клетки для душ и освободившиеся души время от времени испускают крики отчаяния.\n Жертвы в радиусе 3 м от места попадания получают 36136 ед. урона от темной магии и отбрасываются.\n На месте попадания появляется зона отчаяния, наносящие 13551 ед. урона от темной магии раз в секунду."}
MultiLanguageSpellData['ru'][356384] = {name = "Раздавить", additional_info = "Применение: 2 сек\n[q]Stuns all enemies in front of the caster, rendering them unable to move or attack for 2 сек.\n Inflicts 25 Physical damage to all enemies in front of the caster."}
MultiLanguageSpellData['ru'][356385] = {name = "Сгусток гнева", additional_info = "Мгновенное действие\n[q]Призывает эгиду Аннгильды, в течение 8 сек. уменьшающую урон, получаемый от противников перед вами, на 1799 ед.\n\n Поглотив 6297 ед. урона, эгида перегружается и высвобождает накопленную энергию, нанося противникам перед вами 1003 ед. урона от светлой магии."}
MultiLanguageSpellData['ru'][356386] = {name = "Призыв стаи", additional_info = "{Применение: 2 сек} {Восстановление: 40 сек}\n[q]Призывает на помощь сланцевиков-раздирателей."}
