MultiLanguageSpellData['ru'][358711] = {name = "Ярость", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Темные часовые впадают в слепую ярость, сосредотачивая внимание на одной цели и отказываясь атаковать других игроков. Раз в 4.5 сек. каждый темный часовой получает еще один эффект \" Ярость \", увеличивающий наносимый урон на 10% и не дающий замедлиться ниже 20% обычной скорости. Эффект суммируется."}
MultiLanguageSpellData['ru'][358712] = {name = "Эгида Аннгильды", additional_info = "{Мгновенное действие} {Восстановление: 1.5 мин}\n[q]Призывает эгиду Аннгильды, в течение 8 сек. уменьшающую урон, получаемый от противников перед вами, на 1799 ед.\n\n Поглотив 6297 ед. урона, эгида перегружается и высвобождает накопленную энергию, нанося противникам перед вами 1003 ед. урона от светлой магии."}
