MultiLanguageSpellData['ru'][359372] = {name = "Раптора Утробы", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"После вторжения Тюремщика Зерет Мортис синтезировал новый вид раптор, устойчивых к губительной энергии Утробы.\"\nПрофессия:\nпротосинтез"}
MultiLanguageSpellData['ru'][359373] = {name = "Раптора-охотница", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Рапторы-охотницы были одним из первых вариантов этого вида – идеальные существа для своей экологической ниши. Сегодня их синтезируют по тому же образцу, что и многие века назад.\"\nПрофессия:\nпротосинтез"}
