MultiLanguageSpellData['ru'][364733] = {name = "Яростный перезвон", additional_info = "[q]Израсходовав 3 заряд, \"Тотем вечернего колокола\" испускает вспышку, нанося противникам ([300% of Spell Power]) ед. урона от тайной магии и восполняя союзникам ([110% of Spell Power]) ед. здоровья. Радиус действия – 15 м."}
MultiLanguageSpellData['ru'][364734] = {name = "Проводник стихий", additional_info = "[q]К союзникам, исцеленным \"Цепной жатвой\", применяется \"Быстрина\" (вплоть до 5 целей). К противникам, получившим урон от \"Цепной жатвы\", применяется \"Огненный шок\" (вплоть до 5 целей). Критические эффекты \"Огненного шока\" сокращают время восстановления \"Цепной жатвы\" на 1.0 сек."}
MultiLanguageSpellData['ru'][364735] = {name = "Семена буйной поросли", additional_info = "[q]Каждый раз, когда \"Волшебное переливание\" наносит урон, время восстановления \"Духа дикого зверя\" сокращается на 9.0 сек. , а вероятность критического удара повышается на 4% на 15 сек."}
