MultiLanguageSpellData['ru'][364750] = {name = "Призыв зловещих охотников", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Призывает 2 зловещего охотника, который атакует цель в течение 12 сек."}
MultiLanguageSpellData['ru'][364751] = {name = "Призыв зловещих охотников", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Вызывает демонический метеорит, наполненный дикими бесами, которые атакуют цель.\n\n Метеорит наносит до [3 * ([55.6876% of Spell Power])] ед. урона от пламени Тьмы противникам в радиусе 8 м от цели [ Длань судьбы : поражает каждую цель эффектом \"Рок\" ] и в зависимости от количества поглощенных осколков души призывает до 3 диких бесов:диких бесов."}
MultiLanguageSpellData['ru'][364752] = {name = "Неутолимый голод", additional_info = "[q]По завершении действия \"Клубящийся туман\" наносит ([86.42% of Attack Power]) ед. урона от темной магии максимум 5 находящимся рядом противникам, восполняя вам здоровье в объеме 25% нанесенного урона. Урон увеличивается на 2% за каждые 1 ед. силы рун, затраченной во время действия \"Клубящегося тумана\"."}
MultiLanguageSpellData['ru'][364753] = {name = "Восстановление схемы: Протощекоток", additional_info = "Мгновенное действие\n[q]Загружает в протокузню схему Протощекотока, позволяя вам создавать его с помощью протосинтеза."}
MultiLanguageSpellData['ru'][364754] = {name = "Бешенство поганища", additional_info = "[q]Увеличивает время действия \"Руки поганища\" на 4 сек. и сокращает интервал между получением [ Кровь : \"Костяного щита\" / Лед : \"Инея\" / Нечестивость : \"Рунической порчи\" ] на 2 сек. Когда \"Рука поганища\" впервые наносит урон противнику, эта цель получает от вас на 20% больше урона в течение 12 сек."}
MultiLanguageSpellData['ru'][364755] = {name = "Безудержное перенаправление", additional_info = "[q]\"Дань смерти\" повышает силу еще на 3%, а эффект длится на 2 сек. дольше. Пока вы находитесь в области действия \"Дани смерти\", скорость накопления силы рун повышается на 20%."}
