MultiLanguageSpellData['ru'][364904] = {name = "Антиматерия", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Сфера антиматерии наносит пораженным игрокам 83539 ед. космического урона.\n Антиматерия увеличивает урон, получаемый целью от других сфер антиматерии, на 100% на 10 сек. Эффект суммируется."}
MultiLanguageSpellData['ru'][364905] = {name = "Ослепительная вспышка", additional_info = "Радиус действия: 20 м\n{Применение: 1.5 сек} {Восстановление: 1 сек}\n[q]Disorients enemies within 10 yards of the caster for 3 сек.\n Inflicts 25 Arcane damage to enemies within 10 yards."}
MultiLanguageSpellData['ru'][364906] = {name = "Срыгивание", additional_info = "Мгновенное действие\n[q]Сколекс поворачивается к случайному игроку и изрыгает растворяющую реальность кислоту на всех игроков перед собой, нанося 11 ед. урона мгновенно и еще 11 ед. урона от темной магии раз в 5.2 сек. в течение до отмены.\n\n Кроме того, пораженные игроки дважды телепортируются случайным образом ."}
