MultiLanguageSpellData['ru'][364935] = {name = "Мешочек гниющих душ", additional_info = "[q]\"Гниение души\" повышает вашу скорость и вероятность критического удара на 5% на 8 сек. за каждую пораженную цель."}
MultiLanguageSpellData['ru'][364936] = {name = "Осколок аннигиляции", additional_info = "[q]\"Стрела опустошения\" также повышает вероятность критического эффекта [ Разрушение : \"Испепеления\" / Похищение души : \"Похищения души\" ] [ Демонология : \"Демонического заряда\" /\n\nКолдовство\n \"Стрелы Тьмы\" ] на 100% и увеличивает урон от критических эффектов этой способности на 50%."}
MultiLanguageSpellData['ru'][364937] = {name = "Чахлые обломки души", additional_info = "[q]Когда \"Очищающее пожертвование\" дает осколки души, ваша скорость передвижения повышается на 100%, а вероятность критического удара – на 45%. Время действия – 8 сек. Если время действия \"Очищающего пожертвования\" заканчивается, ваша скорость передвижения повышается на 33%, а вероятность критического удара – на 15%."}
MultiLanguageSpellData['ru'][364938] = {name = "Контролируемый бесконечный взрыв", additional_info = "[q]Периодический урон от \"Неотвратимой катастрофы\" увеличивается на 125% и еще на 15% за каждого противника, пораженного этой способностью на пути к цели, вплоть до 275%."}
