MultiLanguageSpellData['ru'][370818] = {name = "Мгновенный огонь", additional_info = "Мгновенное действие\n[q]\"Погребальный костер\" и \"Живой жар\" с вероятностью 15% увеличивают урон от следующей \"Огненной бури\" на 100% и позволяют применить ее мгновенно и без запуска времени восстановления."}
MultiLanguageSpellData['ru'][370819] = {name = "Обжигающие угли", additional_info = "[q]Противники, пораженные \"Огненным дыханием\", получают до 40% дополнительного урона от ваших красных заклинаний. Прибавка к урону зависит от уровня усиления."}
