MultiLanguageSpellData['ru'][374352] = {name = "Энергетическая бомба", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Эхо Дорагосы отмечает игрока чародейским знаком на 6 сек. По истечении времени действия \" Энергетическая бомба \" наносит игрокам в радиусе 8 м 4359790 ед. урона от тайной магии.\n\n Применяет к цели эффект \" Переполняющая энергия \"."}
MultiLanguageSpellData['ru'][374355] = {name = "Разгоряченные удары", additional_info = "Мгновенное действие\n[q]Главный кузнец проводит две атаки, нанося 40 ед. физического урона каждым ударом и отбрасывая цель.\n\n После этого он прыгает к цели и наносит мощный удар раскаленным молотом, нанося игрокам в радиусе 8 м 100 ед. физического урона и 35 ед. урона от огня."}
MultiLanguageSpellData['ru'][374358] = {name = "Злобность", additional_info = "[q]\"Божественная звезда\" и \"Сияние\" теперь наносят урон от темной магии и получают дополнительный эффект:\n\n Порочная звезда :\n\"Божественная звезда\" наносит пораженным противникам еще ([120% of Spell Power]) ед. урона от темной магии за 6 сек. Кроме того, урон от \"Божественной звезды\" увеличивается на 10% каждый раз, когда она поражает противника, вплоть до 100%.\n\n Недоброе сияние :\n\"Сияние\" наносит пораженным противникам еще ([120% of Spell Power]) ед. урона от темной магии за 6 сек. Каждый противник, пораженный \"Сиянием\", сокращает время восстановления способности на 3 сек. вплоть до 15 сек."}
