MultiLanguageSpellData['ru'][376910] = {name = "Бурый боевой выдрек", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Искарские клыкарры ненавидят проливать кровь, но многие из них все же взялись за копье и пошли в бой вместе с верными боевыми выдреками.\"\nискарские клыкарры\nИзвестность:\n30\nТорговец:\nТатто\nЗона:\nИскара\nЦена:\n5\n5\n1000"}
