MultiLanguageSpellData['ru'][385399] = {name = "Высвобожденное разрушение", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Мраскул высвобождает волну чародейской энергии, отталкивающую игроков и наносящую 2909339 ед. урона от тайной магии."}
