MultiLanguageSpellData['ru'][394111] = {name = "Ярость Элуны", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Луч чистой небесной энергии преследует противника, нанося [8 * 2 * ([19.3% of Spell Power])] ед. астрального урона за 8 сек. Дополнительные цели получают меньше урона.\n\nДает 40 ед. астральной мощи за время действия."}
MultiLanguageSpellData['ru'][394112] = {name = "Бегство от реальности", additional_info = "Мгновенное действие\n[q]После применения \"Трансцендентности: перенос\" вы можете снова применить \"Трансцендентность: перенос\" в течение 10 сек., несмотря на время восстановления.\n\n Если в это время вы применяете \"Оживить\" к себе, исцеление от него усиливается на 70%%, а вы восполняете 50% затраченного ресурса."}
