MultiLanguageSpellData['ru'][397399] = {name = "Камень теней исцелителя Бездны", additional_info = "{Мгновенное действие} {Восстановление: 1.5 мин}\nСрабатывает приблизительно 20 раз(а) в минуту\n[q]Сила самоцвета повышает вашу вероятность критического удара на 219 на 15 сек. Ваши исцеляющие наносящие урон заклинания и способности с высокой вероятностью заряжают самоцвет, усиливая эффект."}
MultiLanguageSpellData['ru'][397400] = {name = "Отросток Костебрюха", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Вы откусываете от отростка, в результате чего ваша вероятность критического удара повышается на 178 на 20 сек. и исторгаете зловонное дыхание, наносящее ( 397 * 20 / 5) ед. урона от темной магии, распределяемого между противниками в секторе перед вами."}
